const DEMO = true; // set false for live quiet hours
const OPEN = 15;
const CLOSE = 21;
const now = new Date();
if (DEMO) {
  return [{ json: { ...$input.first().json, sendWindow: 'DEMO (no hold)', holdUntilWindow: false, waitMinutes: 0, sendAt: now.toISOString(), demo: true } }];
}
const parts = Object.fromEntries(new Intl.DateTimeFormat("en-GB", { timeZone: "Africa/Nairobi", hour: "numeric", minute: "numeric", hourCycle: "h23" })
    .formatToParts(now)
    .map((part) => [part.type, part.value]));
const hour = Number(parts.hour) + Number(parts.minute) / 60;
let waitMinutes = 0;
if (hour < OPEN)
    waitMinutes = Math.ceil((OPEN - hour) * 60);
else if (hour >= CLOSE)
    waitMinutes = Math.ceil((24 - hour + OPEN) * 60);
return [
    {
        json: {
            ...$input.first().json,
            sendWindow: `${OPEN}:00–${CLOSE}:00 Nairobi`,
            holdUntilWindow: waitMinutes > 0,
            waitMinutes,
            sendAt: new Date(now.getTime() + waitMinutes * 60_000).toISOString(),
            demo: false,
        },
    },
];

const info = $("Order & viewer (storefront)").first().json || {};
const event = $("Normalize abandon").first().json || {};
const order = info.order || {};
const user = info.user || {};
const cartIds = Array.isArray(order.movieIds) ? order.movieIds.filter(Boolean) : [];
const fallbackId = event.movieId || (event.properties && event.properties.movieId) || 'nairobi-half-life';
const baseIds = cartIds.length ? cartIds : [fallbackId];
const raw = $input.first().json || {};
const picks = (raw.data && Array.isArray(raw.data.items) ? raw.data.items : [])
  .filter((item) => item && item.movieId && !baseIds.includes(item.movieId) && !(info.ownedMovieIds || []).includes(item.movieId));
const pick = picks[0] || null;
const movieIds = pick ? [baseIds[0], pick.movieId].filter(Boolean) : baseIds;
if (!movieIds.length) {
  return [{ json: { userId: user.id || event.userId || null, orderId: order.id || event.orderId || null, movieIds: [fallbackId], discountPct: 10, pick: null, error: 'no_movies_fallback' } }];
}
return [{
  json: {
    userId: user.id || event.userId || null,
    orderId: order.id || event.orderId || null,
    movieIds,
    discountPct: pick ? 20 : 10,
    pick: pick ? { title: pick.title, reason: pick.reason, genres: pick.genres, why: pick.why || null } : null,
  },
}];

const info = $("Order & viewer (storefront)").first().json || {};
const event = $("Normalize abandon").first().json || {};
const bundle = $("Build the bundle").first().json || {};
const raw = $("Offer link (storefront)").first().json || {};
const link = (raw && raw.nudgeId) ? raw : (raw.body || raw.data || raw);
const films = Array.isArray(link.films) ? link.films : [];
const [cart, extra] = films;
const user = info.user || {};
const first = user.firstName || 'there';
const cartTitle = (cart && cart.title) || (info.order && info.order.movieTitle) || event.movieTitle || 'your film';
const pickTitle = (extra && extra.title) || (bundle.pick && bundle.pick.title) || null;
const pickReason = (bundle.pick && (bundle.pick.reason || (bundle.pick.why && bundle.pick.why.matchedGenres && bundle.pick.why.matchedGenres.join(', ')))) || '';
const poster = (cart && (cart.poster || cart.posterUrl || cart.image)) || (extra && (extra.poster || extra.posterUrl)) || '';
const subject = pickTitle
  ? `${first}, ${cartTitle} + ${pickTitle} — still waiting`
  : `${first}, ${cartTitle} is still waiting for you`;
const body = pickTitle
  ? `Hi ${first} — ${cartTitle} is saved in your cart. Grab it with ${pickTitle} for KES ${link.totalKes} (${link.discountPct}% off this hour):`
  : `Hi ${first} — ${cartTitle} is still waiting. Finish for KES ${link.totalKes} (${link.discountPct}% off this hour):`;
const url = link.url || '';
const message = `${body} ${url}`.trim();
return [{
  json: {
    userId: user.id || event.userId || null,
    orderId: (info.order && info.order.id) || event.orderId || null,
    phone: user.phone || event.phone || '',
    email: user.email || event.email || '',
    name: user.name || event.name || first,
    channelPref: user.channelPref || user.channel_pref || event.channel_pref || 'both',
    subject,
    scenario: 'A_abandon',
    firstName: first,
    filmTitle: cartTitle,
    cartTitle,
    title: cartTitle,
    pickTitle,
    pickReason,
    bundleTitle: pickTitle,
    totalKes: link.totalKes,
    priceKes: link.totalKes,
    discountPct: link.discountPct,
    url,
    ctaUrl: url,
    ctaLabel: 'Finish checkout',
    imageUrl: poster,
    films,
    nudgeId: link.nudgeId,
    movieIds: films.map((f) => f.id),
    message,
    fallback: body,
    alternative: '',
  },
}];

const raw = $input.first().json || {};
let j = raw;
if (typeof raw.content === 'string') {
  try { j = JSON.parse(raw.content); } catch (e) { j = raw; }
} else if (raw.content && typeof raw.content === 'object') {
  j = raw.content;
}
const props = j.properties || {};
const userId = j.userId || j.user_id || props.userId || '';
const orderId = j.orderId || props.orderId || '';
const email = j.email || props.email || '';
const phone = j.phone || props.phone || '';
const name = j.name || props.name || '';
const movieId = j.movie_id || props.movieId || '';
const movieTitle = j.movie_title || props.movieTitle || '';
return [{
  json: {
    ...j,
    userId,
    user_id: userId,
    orderId,
    email,
    phone,
    name,
    movieId,
    movieTitle,
    channel_pref: j.channel_pref || props.channelPref || 'both',
    properties: {
      ...props,
      orderId,
      movieId,
      movieTitle,
      email,
      phone,
      name,
      channelPref: j.channel_pref || props.channelPref || 'both',
    },
  },
}];

let message = '';
let error = null;
try {
  const raw = $input.first().json || {};
  if (raw.error || raw.message === 'Unauthorized' || raw.code === 401) {
    error = String(raw.error || raw.message || 'openrouter_error');
  }
  const content = (raw.choices && raw.choices[0] && raw.choices[0].message && raw.choices[0].message.content)
    || raw.message || '';
  if (typeof content === 'string' && content.trim().startsWith('{')) {
    const parsed = JSON.parse(content);
    message = String(parsed.message || parsed.text || '').trim();
  } else if (typeof content === 'string' && !error) {
    message = content.trim();
  }
} catch (e) {
  message = '';
  error = String(e.message || e);
}
return [{ json: { output: { message }, text: message, error } }];

const facts = $("Offer facts").first().json || {};
const ai = $input.first().json || {};
const text = String((ai.output && ai.output.message) || ai.text || '').trim();
let fallbackReason = null;
if (!text)
  fallbackReason = ai.error ? ('AI error: ' + ai.error) : 'no AI answer';
else if (text.length > 120)
  fallbackReason = 'too long';
else if (/https?:|www\.|\.com|\.app/i.test(text))
  fallbackReason = 'contains a link';
else {
  const prices = [...text.matchAll(/KES\s?([\d,]+)/gi)].map((m) => Number(m[1].replace(/,/g, '')));
  if (facts.totalKes != null && prices.some((p) => p !== Number(facts.totalKes)))
    fallbackReason = 'wrong price';
}
const body = fallbackReason ? (facts.fallback || facts.message || '') : text;
const url = facts.url || '';
const message = `${body} ${url}`.trim();
return [{
  json: {
    ...facts,
    message,
    aiUsed: !fallbackReason,
    fallbackReason,
    subject: facts.subject || 'Yakwetu Sinema',
  },
}];
